def settings(prefix):
    return f'''<div class="settings-fields"><div class="field"><label for="{prefix}theme" data-i18n="theme">Тема</label><select id="{prefix}theme" data-setting="theme"><option value="dark" data-i18n="dark">Тёмная</option><option value="light" data-i18n="light">Светлая</option></select></div><div class="field"><label for="{prefix}font" data-i18n="fontSize">Размер текста</label><select id="{prefix}font" data-setting="font"><option value="small" data-i18n="small">Мелкий</option><option value="medium" data-i18n="medium">Обычный</option><option value="large" data-i18n="large">Крупный</option></select></div><div class="field"><label for="{prefix}language" data-i18n="language">Язык</label><select id="{prefix}language" data-setting="language"><option value="ru">Русский</option><option value="en">English</option></select></div></div><details class="api-help"><summary data-i18n="apiSettings">Внешний API Steam</summary><p data-i18n="apiHint">Необязательно. Только адрес вашего HTTPS-сервиса с CORS. Ключ Steam хранится на сервере, не здесь.</p><label for="{prefix}api" data-i18n="apiUrl">Адрес API</label><input id="{prefix}api" type="url" data-setting="api" placeholder="https://your-service.example" autocomplete="off" spellcheck="false"><p data-i18n="apiPrivacy">При проверке идентификатор будет отправлен этому сервису.</p><p class="mono">GET /players/{{steamid}}</p></details>'''

for path, (name, title, no, content) in PAGES.items():
    base = './' if path == 'index.html' else '../'
    nav = ''
    for n, label, href, idx in [('checker','checker','index.html','01'),('raider','raid','raider/','02'),('recycler','recycle','recycler/','03')]:
        current = ' aria-current="page"' if n == name else ''
        label_ru = {'checker':'Чекер','raid':'Рейд','recycle':'Переработка'}[label]
        nav += f'<a href="{base}{href}"{current} title="{label_ru}" data-i18n-title="{label}"><span class="nav-index">{idx}</span><span class="tool-label" data-i18n="{label}">{label_ru}</span></a>'
    document = f'''<!doctype html>
<html lang="ru" data-theme="dark"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Rust Util: локальный трекер SteamID, расчёты рейда и переработки для Rust."><meta name="theme-color" content="#101112"><title>{title} — Rust Util</title><link rel="icon" href="{base}assets/mark.svg" type="image/svg+xml"><link rel="stylesheet" href="{base}assets/style.css"><script src="{base}assets/theme.js"></script><script type="module" src="{base}assets/{name}.js"></script></head>
<body data-page="{name}"><a href="#main" class="visually-hidden" data-i18n="skip">К содержимому</a><div class="app"><aside class="sidebar" aria-label="Навигация" data-i18n-aria="navigation"><a class="brand" href="{base}index.html"><img src="{base}assets/mark.svg" alt="" width="34" height="34"><div class="brand-copy"><div class="brand-name">RUST / UTIL</div><div class="brand-by">BY VATRUSHKA</div></div></a><nav class="nav">{nav}</nav><div class="sidebar-end"><button id="collapse-sidebar" class="collapse" type="button" aria-expanded="true"><span id="collapse-glyph" class="mono" aria-hidden="true">[ ← ]</span><span class="collapse-label" data-i18n="collapse">Свернуть</span></button><div class="sidebar-meta">STATIC BUILD / 1.0.0<br>CLIENT-SIDE TOOLS</div></div></aside>
<main id="main" class="workspace"><header class="topbar"><span>RUST UTIL <span aria-hidden="true">/</span> <code data-i18n="{name}">{title}</code></span><span class="mode"><span class="mode-dot" aria-hidden="true"></span><span data-i18n="localMode">Локальный режим</span></span></header><div class="page-intro"><div class="eyebrow">MODULE {no} / RUST UTIL</div><h1 data-i18n="{name}Title">{title}</h1><p data-i18n="{name}Intro"></p></div><div id="storage-error" class="notice error" role="alert" hidden></div>{content}<details class="panel mobile-settings"><summary data-i18n="settings">Настройки</summary>{settings('mobile-')}</details><footer class="workspace-footer"><span>v1.0.0 / vatrushka</span><a href="https://github.com/bobosneefdev/rust-items-json" target="_blank" rel="noopener noreferrer" data-i18n="dataSource">Источник игровых данных</a></footer></main>
<aside class="rightbar"><div class="eyebrow">CONFIGURATION</div><h2 data-i18n="settings">Настройки</h2>{settings('desktop-')}<hr class="divider"><div class="system-label" data-i18n="storageLabel">Хранение</div><div class="system-value">localStorage / JSON</div><p style="margin-top:10px" data-i18n="storageHint">Данные привязаны к браузеру и адресу сайта. Экспортируйте список перед очисткой хранилища.</p><hr class="divider"><div class="system-label" data-i18n="dataSnapshot">Снимок данных</div><div id="data-version" class="system-value">—</div><p data-i18n="affiliation">Независимый проект. Не связан с Facepunch Studios или Valve.</p></aside></div><div id="flash" class="flash" role="status" aria-live="polite" hidden></div><noscript><div class="notice">Для работы утилиты включите JavaScript. / Enable JavaScript to use the tools.</div></noscript></body></html>'''
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(document + '\n')
(ROOT / '.nojekyll').touch()
(ROOT / 'manus-routes.json').write_text(json.dumps({'routes':[{'path':'/','title':'Проверка игрока'},{'path':'/raider/','title':'Калькулятор рейда'},{'path':'/recycler/','title':'Калькулятор переработки'}]},ensure_ascii=False) + '\n')
(ROOT / '404.html').write_text('''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>404 — Rust Util</title><body style="background:#101112;color:#e5e7e8;font:16px monospace;padding:40px"><h1>404 / Rust Util</h1><p>Страница не найдена. / Page not found.</p><a href="./" style="color:#ff8c77">Главная / Home</a></body></html>\n''')
